# ---------------------------------------------------------------------------
# Configuration and scene helpers


def rear_wall_fans_enabled() -> bool:
    return FAN_MOUNT_MODE == "rear_wall_pair"


def lid_fan_enabled() -> bool:
    return FAN_MOUNT_MODE in {"lid_single", "lid_pair"}


def lid_fan_count() -> int:
    """Return the number of equal fans mounted on the removable lid."""
    if FAN_MOUNT_MODE == "lid_single":
        return 1
    if FAN_MOUNT_MODE == "lid_pair":
        return 2
    return 0


def case_body_uses_tpu() -> bool:
    return CASE_BODY_MATERIAL_MODE == "TPU"


def lid_uses_tpu() -> bool:
    return LID_MATERIAL_MODE == "TPU"


def case_body_fastener_profile(
    rigid_hole_diameter: float,
    rigid_hole_depth: float,
    rigid_leadin_diameter: float | None = None,
    rigid_leadin_depth: float = 0.0,
):
    """Resolve a base-owned M3 receiver for the configured body material."""
    if case_body_uses_tpu():
        return {
            "style": "pointed_M3_self_tapping",
            "hole_diameter": CASE_BODY_TPU_M3_PILOT_DIAMETER,
            "hole_depth": min(
                rigid_hole_depth,
                CASE_BODY_TPU_M3_PILOT_MAX_DEPTH,
            ),
            "leadin_diameter": CASE_BODY_TPU_M3_PILOT_DIAMETER,
            "leadin_depth": 0.0,
        }
    return {
        "style": "M3_heat_insert",
        "hole_diameter": rigid_hole_diameter,
        "hole_depth": rigid_hole_depth,
        "leadin_diameter": (
            rigid_hole_diameter
            if rigid_leadin_diameter is None
            else rigid_leadin_diameter
        ),
        "leadin_depth": rigid_leadin_depth,
    }


def front_lid_anchor_profile():
    """Return the material-specific hidden front tongue/receiver dimensions."""
    body_suffix = "TPU" if case_body_uses_tpu() else "RIGID"
    lid_suffix = "TPU" if lid_uses_tpu() else "RIGID"
    return {
        "slot_depth": globals()[f"LID_FRONT_ANCHOR_{body_suffix}_SLOT_DEPTH"],
        "tab_width": globals()[f"LID_FRONT_ANCHOR_{lid_suffix}_TAB_WIDTH"],
        "tab_thickness": globals()[
            f"LID_FRONT_ANCHOR_{lid_suffix}_TAB_THICKNESS"
        ],
        "root_length": globals()[f"LID_FRONT_ANCHOR_{lid_suffix}_ROOT_LENGTH"],
        "fit_clearance": globals()[
            f"LID_FRONT_ANCHOR_{body_suffix}_FIT_CLEARANCE"
        ],
        "receiver_wall": globals()[
            f"LID_FRONT_ANCHOR_{body_suffix}_RECEIVER_WALL"
        ],
    }


def effective_front_lid_lip_depth() -> float:
    """Return the nose lip depth compatible with the selected hold-down."""
    if LID_FRONT_ANCHOR_ENABLED:
        return LID_LIP_DEPTH
    if LID_FRONT_INSERT_LIP_ENABLED:
        return LID_FRONT_INSERT_LIP_DEPTH
    return LID_LIP_DEPTH


def lid_fan_cover_profile():
    if LID_FAN_COVER_MATERIAL_MODE == "TPU":
        return {
            "fit_clearance": LID_FAN_COVER_TPU_FIT_CLEARANCE,
            "wall_thickness": LID_FAN_COVER_TPU_WALL_THICKNESS,
            "grille_thickness": LID_FAN_COVER_TPU_GRILLE_THICKNESS,
            "retention_protrusion": (
                LID_FAN_COVER_TPU_RETENTION_PROTRUSION
            ),
            "grille_detent_protrusion": (
                LID_FAN_GRILLE_TPU_DETENT_PROTRUSION
            ),
        }
    return {
        "fit_clearance": LID_FAN_COVER_RIGID_FIT_CLEARANCE,
        "wall_thickness": LID_FAN_COVER_RIGID_WALL_THICKNESS,
        "grille_thickness": LID_FAN_COVER_RIGID_GRILLE_THICKNESS,
        "retention_protrusion": (
            LID_FAN_COVER_RIGID_RETENTION_PROTRUSION
        ),
        "grille_detent_protrusion": (
            LID_FAN_GRILLE_RIGID_DETENT_PROTRUSION
        ),
    }


def lid_fan_grille_pattern_profile():
    """Scale turbine details so small TPU grilles remain strong and open."""
    frame_scale = lid_fan_reference_dimensions()["frame"] / 120.0
    return {
        "hub_radius": max(
            3.0,
            LID_FAN_COVER_CENTER_HUB_DIAMETER * frame_scale / 2.0,
        ),
        "border_width": max(
            1.2,
            LID_FAN_COVER_BORDER_WIDTH * frame_scale,
        ),
        "ring_width": max(0.9, LID_FAN_COVER_RING_WIDTH * frame_scale),
        "ring_radii_fractions": (
            ()
            if lid_fan_reference_dimensions()["frame"] <= 40.0
            else LID_FAN_COVER_RING_RADII_FRACTIONS
        ),
        "spoke_width": max(
            1.2,
            LID_FAN_COVER_SPOKE_WIDTH * frame_scale,
        ),
        "spoke_count": (
            6
            if lid_fan_reference_dimensions()["frame"] < 80.0
            else LID_FAN_COVER_SPOKE_COUNT
        ),
    }


def fan_acoustic_attenuator_enabled() -> bool:
    """The existing labyrinth is specific to the paired rear-wall fans."""
    return rear_wall_fans_enabled() and FAN_ACOUSTIC_ATTENUATOR_ENABLED


def lid_fan_reference_dimensions():
    """Return the shared standard frame/depth/hole/opening/hub dimensions."""
    preset = get_standard_fan_preset(LID_FAN_SIZE_MM)
    return {
        "frame": float(preset["frame"]),
        "depth": (
            float(preset["depth"])
            if LID_FAN_DEPTH_MM is None
            else float(LID_FAN_DEPTH_MM)
        ),
        "mount_spacing": (
            float(preset["hole_spacing"])
            if LID_FAN_MOUNT_SPACING_MM is None
            else float(LID_FAN_MOUNT_SPACING_MM)
        ),
        "opening": (
            float(preset["opening"])
            if LID_FAN_AIR_OPENING_DIAMETER_MM is None
            else float(LID_FAN_AIR_OPENING_DIAMETER_MM)
        ),
        "hub": (
            float(preset["hub"])
            if LID_FAN_HUB_DIAMETER_MM is None
            else float(LID_FAN_HUB_DIAMETER_MM)
        ),
        "reference": str(preset["reference"]),
    }


def lid_fan_unit_centers():
    """Return one center per fan, with dual fans arranged across the lid."""
    count = lid_fan_count()
    if count == 0:
        return ()
    center_x = float(LID_FAN_CENTER_X)
    center_y = float(LID_FAN_CENTER_Y)
    if count == 1:
        return ((center_x, center_y),)
    pitch = (
        lid_fan_reference_dimensions()["frame"]
        + LID_FAN_PAIR_FRAME_GAP_MM
    )
    return (
        (center_x, center_y - pitch / 2.0),
        (center_x, center_y + pitch / 2.0),
    )


def lid_fan_array_dimensions():
    """Return the rectangular envelope of all configured lid-fan frames."""
    dimensions = lid_fan_reference_dimensions()
    frame = dimensions["frame"]
    count = lid_fan_count()
    return {
        "center_x": float(LID_FAN_CENTER_X),
        "center_y": float(LID_FAN_CENTER_Y),
        "width_x": frame,
        "depth_y": count * frame + max(count - 1, 0) * LID_FAN_PAIR_FRAME_GAP_MM,
    }


def lid_fan_flat_seat_dimensions():
    array = lid_fan_array_dimensions()
    return (
        array["width_x"] + 2.0 * LID_FAN_FLAT_SEAT_EDGE_MARGIN,
        array["depth_y"] + 2.0 * LID_FAN_FLAT_SEAT_EDGE_MARGIN,
    )


def lid_fan_pod_plan_dimensions():
    """Resolve the shared fairing, grille, rails, and detent plan geometry."""
    array = lid_fan_array_dimensions()
    profile = lid_fan_cover_profile()
    fairing_top_width = (
        array["width_x"] + 2.0 * LID_FAN_FAIRING_TOP_X_MARGIN
    )
    fairing_top_depth = (
        array["depth_y"] + 2.0 * LID_FAN_FAIRING_TOP_Y_MARGIN
    )
    fairing_top_center_x = (
        array["center_x"] + LID_FAN_FAIRING_TOP_CENTER_X_OFFSET
    )
    # Make the seated grille a parallel inset of the fairing's complete top
    # outline.  The former fan-frame-sized panel left wide crescent gaps at
    # the corners and a still larger rear reveal beside the cable blister.
    grille_perimeter_inset = profile["wall_thickness"]
    grille_width = fairing_top_width - 2.0 * grille_perimeter_inset
    grille_depth = fairing_top_depth - 2.0 * grille_perimeter_inset
    grille_corner_radius = min(
        max(
            0.5,
            LID_FAN_FAIRING_TOP_CORNER_RADIUS - grille_perimeter_inset,
        ),
        grille_width / 4.0,
        grille_depth / 4.0,
    )
    rail_length = (
        grille_width
        - LID_FAN_GRILLE_RAIL_FRONT_ENTRY_CLEARANCE
        + LID_FAN_GRILLE_RAIL_REAR_OVERTRAVEL
    )
    rail_center_offset_x = (
        LID_FAN_GRILLE_RAIL_FRONT_ENTRY_CLEARANCE
        + LID_FAN_GRILLE_RAIL_REAR_OVERTRAVEL
    ) / 2.0
    return {
        **array,
        "fairing_bottom_width": (
            array["width_x"] + 2.0 * LID_FAN_FAIRING_BOTTOM_X_MARGIN
        ),
        "fairing_bottom_depth": (
            array["depth_y"] + 2.0 * LID_FAN_FAIRING_BOTTOM_Y_MARGIN
        ),
        "fairing_bottom_center_x": (
            array["center_x"] + LID_FAN_FAIRING_BOTTOM_CENTER_X_OFFSET
        ),
        "fairing_top_width": fairing_top_width,
        "fairing_top_depth": fairing_top_depth,
        "fairing_top_center_x": fairing_top_center_x,
        "grille_width": grille_width,
        "grille_depth": grille_depth,
        "grille_corner_radius": grille_corner_radius,
        "grille_center_x": fairing_top_center_x,
        "grille_perimeter_inset": grille_perimeter_inset,
        "rail_length": rail_length,
        "rail_center_x": fairing_top_center_x + rail_center_offset_x,
        "detent_front_offset": min(
            LID_FAN_GRILLE_DETENT_FRONT_EDGE_OFFSET,
            grille_width / 2.0,
        ),
    }


def lid_fan_grille_retention_profile():
    """Resolve the grille lock boss, pilot, and material-specific hardware."""
    plan = lid_fan_pod_plan_dimensions()
    screw_length = f"{LID_FAN_GRILLE_RETENTION_RECOMMENDED_SCREW_LENGTH:g}"
    if LID_FAN_COVER_MATERIAL_MODE == "TPU":
        pilot_diameter = LID_FAN_GRILLE_RETENTION_TPU_PILOT_DIAMETER
        receiver_style = "pointed_M3_self_tapping"
        hardware = f"M3x{screw_length}_pointed_self_tapping"
    else:
        pilot_diameter = LID_FAN_GRILLE_RETENTION_RIGID_PILOT_DIAMETER
        receiver_style = "M3_thread_forming_rigid_pilot"
        hardware = f"M3x{screw_length}_thread_forming"
    boss_radius = LID_FAN_GRILLE_RETENTION_BOSS_DIAMETER / 2.0
    return {
        "enabled": bool(LID_FAN_GRILLE_POSITIVE_RETENTION_ENABLED),
        "center": (
            plan["center_x"]
            + plan["width_x"] / 2.0
            + lid_fan_cover_profile()["fit_clearance"]
            + LID_FAN_GRILLE_RETENTION_FAN_FRAME_CLEARANCE
            + boss_radius,
            float(LID_FAN_CENTER_Y),
        ),
        "pilot_diameter": pilot_diameter,
        "receiver_style": receiver_style,
        "hardware": hardware,
    }


def lid_fan_fairing_plan_section(fraction):
    """Return one eased XY section of the tapered fan fairing."""
    plan = lid_fan_pod_plan_dimensions()
    eased = fraction * fraction * (3.0 - 2.0 * fraction)
    return {
        "width": plan["fairing_bottom_width"] + eased * (
            plan["fairing_top_width"] - plan["fairing_bottom_width"]
        ),
        "depth": plan["fairing_bottom_depth"] + eased * (
            plan["fairing_top_depth"] - plan["fairing_bottom_depth"]
        ),
        "center_x": plan["fairing_bottom_center_x"] + eased * (
            plan["fairing_top_center_x"]
            - plan["fairing_bottom_center_x"]
        ),
        "radius": LID_FAN_FAIRING_BOTTOM_CORNER_RADIUS + eased * (
            LID_FAN_FAIRING_TOP_CORNER_RADIUS
            - LID_FAN_FAIRING_BOTTOM_CORNER_RADIUS
        ),
    }


def lid_fan_fairing_retention_receiver_profile():
    """Resolve the lid's blind thread-forming receiver for the fairing."""
    if lid_uses_tpu():
        return {
            "style": "pointed_M3_self_tapping",
            "pilot_diameter": LID_FAN_FAIRING_RETENTION_TPU_PILOT_DIAMETER,
        }
    return {
        "style": "M3_thread_forming_rigid_pilot",
        "pilot_diameter": LID_FAN_FAIRING_RETENTION_RIGID_PILOT_DIAMETER,
    }


def lid_fan_fairing_retention_screw_centers():
    """Return hidden screw axes through the two floor-rooted side ribs."""
    if not (
        lid_fan_enabled()
        and LID_FAN_COVER_ENABLED
        and LID_FAN_FAIRING_POSITIVE_RETENTION_ENABLED
    ):
        return ()
    dimensions = lid_fan_reference_dimensions()
    profile = lid_fan_cover_profile()
    plan = lid_fan_pod_plan_dimensions()
    fairing_height = (
        dimensions["depth"]
        + LID_FAN_COVER_TOP_CLEARANCE
        - profile["fit_clearance"]
    )
    contact_fraction = (
        1.5 * LID_FAN_COVER_RETENTION_PAD_HEIGHT / fairing_height
    )
    section = lid_fan_fairing_plan_section(contact_fraction)
    shell_offset_y = section["depth"] / 2.0
    fan_contact_offset_y = (
        plan["depth_y"] / 2.0
        + profile["fit_clearance"]
        - profile["retention_protrusion"]
    )
    screw_offset_y = (shell_offset_y + fan_contact_offset_y) / 2.0
    return tuple(
        (
            float(LID_FAN_CENTER_X),
            float(LID_FAN_CENTER_Y) + y_sign * screw_offset_y,
        )
        for y_sign in (1.0, -1.0)
    )


def lid_fan_mount_centers():
    half_spacing = lid_fan_reference_dimensions()["mount_spacing"] / 2.0
    return tuple(
        (
            fan_center_x + x_sign * half_spacing,
            fan_center_y + y_sign * half_spacing,
        )
        for fan_center_x, fan_center_y in lid_fan_unit_centers()
        for x_sign in (-1.0, 1.0)
        for y_sign in (-1.0, 1.0)
    )


def lid_fan_cable_slot_tangential_offset() -> float:
    if LID_FAN_CABLE_SLOT_TANGENTIAL_OFFSET is not None:
        return float(LID_FAN_CABLE_SLOT_TANGENTIAL_OFFSET)
    return -15.0 if lid_fan_reference_dimensions()["frame"] >= 100.0 else 0.0


def lid_fan_cable_feedthrough_geometries():
    """Return one small covered cable-only exit per configured lid fan."""
    if not lid_fan_enabled() or not LID_FAN_CABLE_FEEDTHROUGH_ENABLED:
        return ()
    frame = lid_fan_reference_dimensions()["frame"]
    opening = lid_fan_reference_dimensions()["opening"]
    half_frame = frame / 2.0
    tangent = lid_fan_cable_slot_tangential_offset()
    opening_radius = opening / 2.0
    if abs(tangent) >= opening_radius:
        raise ValueError("Fan cable slot misses the main airflow opening")
    opening_boundary_radial = math.sqrt(
        opening_radius * opening_radius - tangent * tangent
    )
    radial_inner = (
        opening_boundary_radial
        - LID_FAN_CABLE_SLOT_AIR_OPENING_OVERLAP
    )
    radial_outer = half_frame + LID_FAN_CABLE_SLOT_OUTSET
    slot_width = radial_outer - radial_inner
    slot_length = (
        LID_FAN_CABLE_OUTER_DIAMETER
        + 2.0 * LID_FAN_CABLE_SLOT_CLEARANCE
    )
    return tuple(
        {
            "fan_index": fan_index,
            "fan_center": (fan_center_x, fan_center_y),
            "center": (
                fan_center_x + (radial_inner + radial_outer) / 2.0,
                fan_center_y + tangent,
            ),
            "x_sign": 1.0,
            "width": slot_width,
            "length": slot_length,
            "frame_outer_x": fan_center_x + half_frame,
            "air_opening_boundary_x": (
                fan_center_x + opening_boundary_radial
            ),
            "cable_route_radius": LID_FAN_CABLE_OUTER_DIAMETER / 2.0,
            "cable_horizontal_start_x": (
                fan_center_x
                + half_frame
                + LID_FAN_CABLE_SLOT_OUTSET
                - LID_FAN_CABLE_OUTER_DIAMETER / 2.0
            ),
            "cable_vertical_x": (
                fan_center_x
                + opening_boundary_radial
                - LID_FAN_CABLE_OUTER_DIAMETER / 2.0
                - LID_FAN_CABLE_SLOT_CLEARANCE / 2.0
            ),
        }
        for fan_index, (fan_center_x, fan_center_y) in enumerate(
            lid_fan_unit_centers(),
            start=1,
        )
    )


def lid_fan_x_retention_pad_centers_y() -> tuple[float, float]:
    """Return cable-safe +X/-X rib stations on real fan-frame spans."""
    center_y = float(LID_FAN_CENTER_Y)
    unit_centers = lid_fan_unit_centers()
    if len(unit_centers) == 2:
        frame = lid_fan_reference_dimensions()["frame"]
        cable_offset = (
            lid_fan_cable_slot_tangential_offset()
            if LID_FAN_CABLE_FEEDTHROUGH_ENABLED
            else 0.0
        )
        outer_sign = -1.0 if cable_offset > 0.0 else 1.0
        rear_fan_center_y = (
            max(point[1] for point in unit_centers)
            if outer_sign > 0.0
            else min(point[1] for point in unit_centers)
        )
        front_fan_center_y = (
            min(point[1] for point in unit_centers)
            if outer_sign > 0.0
            else max(point[1] for point in unit_centers)
        )
        # Put the +X rib on the outer wing opposite the cable offset.  Its
        # 22 mm span clears that fan's cable chase while still overlapping
        # 14 mm of purchased frame.  The -X side has no chase, so it can bear
        # at the opposite fan's center for distributed retention.
        rear_y = rear_fan_center_y + outer_sign * (frame / 2.0 - 3.0)
        return rear_y, front_fan_center_y
    candidates = (
        center_y,
        center_y + LID_FAN_COVER_RETENTION_PAD_LENGTH,
        center_y - LID_FAN_COVER_RETENTION_PAD_LENGTH,
    )
    cable_center_ys = tuple(
        float(feedthrough["center"][1])
        for feedthrough in lid_fan_cable_feedthrough_geometries()
    )
    if not cable_center_ys:
        return center_y, center_y
    rear_y = max(
        candidates,
        key=lambda candidate: min(
            abs(candidate - cable_center_y)
            for cable_center_y in cable_center_ys
        ),
    )
    frame = lid_fan_reference_dimensions()["frame"]
    if not any(
        abs(rear_y - fan_center_y) <= frame / 2.0
        for _fan_center_x, fan_center_y in unit_centers
    ):
        # A 22 mm offset clears a centered lead on 60/80 mm frames but its
        # probe would sit beyond a single 40 mm frame.  Keep the rib on that
        # compact frame's outer wing while retaining the same cable gap.
        selected_side = math.copysign(1.0, rear_y - center_y)
        rear_y = center_y + selected_side * (frame / 2.0 - 3.0)
    return rear_y, center_y


def circular_feature_intersects_lid_fan(position, feature_radius: float) -> bool:
    """Conservative plan keepout for lid posts around the fan seat."""
    if not lid_fan_enabled():
        return False
    seat_width, seat_depth = lid_fan_flat_seat_dimensions()
    clearance = feature_radius + LID_FAN_FASTENER_KEEPOUT_CLEARANCE
    return (
        abs(position[0] - LID_FAN_CENTER_X) < seat_width / 2.0 + clearance
        and abs(position[1] - LID_FAN_CENTER_Y) < seat_depth / 2.0 + clearance
    )


def point_inside_rounded_rectangle(
    point,
    width: float,
    height: float,
    radius: float,
) -> bool:
    """Test a centered 2D point against a rounded rectangle."""
    half_width = width / 2.0
    half_height = height / 2.0
    radius = min(max(radius, 0.0), half_width, half_height)
    x = abs(point[0])
    z = abs(point[1])
    if x > half_width or z > half_height:
        return False
    dx = max(x - (half_width - radius), 0.0)
    dz = max(z - (half_height - radius), 0.0)
    return dx * dx + dz * dz <= radius * radius + 1e-9


def camera_eye_center_z() -> float:
    if EYE_CENTER_Z is not None:
        return float(EYE_CENTER_Z)
    camera_vertical_min = mission1.canonical_vertical_bounds(
        CAMERA_UPSIDE_DOWN
    )[0]
    return (
        BOTTOM_THICKNESS
        + CAMERA_FLOOR_CLEARANCE
        - camera_vertical_min
    )


def camera_lens_face_outset() -> float:
    if _RESOLVED_CAMERA_LENS_FACE_OUTSET is not None:
        return _RESOLVED_CAMERA_LENS_FACE_OUTSET
    if CAMERA_FORWARD_PLACEMENT_MODE == "manual":
        return float(CAMERA_LENS_FACE_OUTSET)
    return camera_theoretical_lens_face_outset()


def camera_theoretical_lens_face_outset() -> float:
    """Maximum outset at the configured fixed-camera datum projection."""
    body_radial = mission1.canonical_body_bounds(CAMERA_UPSIDE_DOWN)[0]
    return (
        -body_radial[1]
        - EYE_MOUTH_FACE_INSET
        - EYE_FRONT_DATUM_DEPTH
        - CAMERA_FRONT_STOP_PROJECTION
    )


def camera_lens_face_outset_for(camera) -> float:
    """Actual lens-face outset from this eye's unrecessed shell surface."""
    return (
        camera["radial"]
        + CAMERA_BODY_DEPTH / 2.0
        - camera["surface"]
    )


def eye_front_datum_plane_from_surface(surface: float) -> float:
    """Abstract radial plane used by the independent camera front datums."""
    return (
        surface
        - EYE_MOUTH_FACE_INSET
        - EYE_FRONT_DATUM_DEPTH
    )


def eye_front_datum_plane(camera) -> float:
    return eye_front_datum_plane_from_surface(camera["surface"])


def camera_front_stop_projection() -> float:
    """Gap from the configured datum plane to the front-body plane."""
    body_radial = mission1.canonical_body_bounds(CAMERA_UPSIDE_DOWN)[0]
    return -EYE_MOUTH_FACE_INSET - EYE_FRONT_DATUM_DEPTH - (
        camera_lens_face_outset() + body_radial[1]
    )


def camera_front_stop_projection_for(camera) -> float:
    """Actual fixed-camera gap from front body plane to its datum plane."""
    body_radial = mission1.canonical_body_bounds(CAMERA_UPSIDE_DOWN)[0]
    lens_outset = (
        camera_lens_face_outset_for(camera)
        if "surface" in camera
        else camera.get(
            "target_lens_face_outset",
            camera_lens_face_outset(),
        )
    )
    return -EYE_MOUTH_FACE_INSET - EYE_FRONT_DATUM_DEPTH - (
        lens_outset + body_radial[1]
    )


def camera_front_stop_specs():
    """Resolve three contact patches on solid wall and flat camera face."""
    _, body_tangent, body_vertical = mission1.canonical_body_bounds(
        CAMERA_UPSIDE_DOWN
    )
    flat_tangent = (
        body_tangent[0] + mission1.BODY_CORNER_RADIUS,
        body_tangent[1] - mission1.BODY_CORNER_RADIUS,
    )
    flat_vertical = (
        body_vertical[0] + mission1.BODY_CORNER_RADIUS,
        body_vertical[1] - mission1.BODY_CORNER_RADIUS,
    )
    eye_half_width = EYE_MOUTH_WIDTH / 2.0
    eye_half_height = EYE_MOUTH_HEIGHT / 2.0
    land = CAMERA_FRONT_STOP_WALL_LAND

    negative_side_room = -eye_half_width - land - flat_tangent[0]
    positive_side_room = flat_tangent[1] - (eye_half_width + land)
    if negative_side_room >= positive_side_room:
        tangent_max = -eye_half_width - land
        tangent_min = tangent_max - CAMERA_FRONT_STOP_SIDE_WIDTH
    else:
        tangent_min = eye_half_width + land
        tangent_max = tangent_min + CAMERA_FRONT_STOP_SIDE_WIDTH
    if (
        tangent_min < flat_tangent[0] - 1e-6
        or tangent_max > flat_tangent[1] + 1e-6
    ):
        raise ValueError("No flat side land remains for camera front stops")

    vertical_min = max(flat_vertical[0], -eye_half_height + land)
    vertical_max = min(flat_vertical[1], eye_half_height - land)
    side_half_height = CAMERA_FRONT_STOP_SIDE_HEIGHT / 2.0
    side_centers = (
        vertical_min + side_half_height,
        vertical_max - side_half_height,
    )
    if side_centers[1] - side_centers[0] < (
        CAMERA_FRONT_STOP_SIDE_HEIGHT / 2.0
    ):
        raise ValueError("Camera front side stops do not fit vertically")

    bottom_room = -eye_half_height - land - flat_vertical[0]
    top_room = flat_vertical[1] - (eye_half_height + land)
    if bottom_room >= top_room:
        rim_max = -eye_half_height - land
        rim_min = rim_max - CAMERA_FRONT_STOP_RIM_HEIGHT
    else:
        rim_min = eye_half_height + land
        rim_max = rim_min + CAMERA_FRONT_STOP_RIM_HEIGHT
    if (
        rim_min < flat_vertical[0] - 1e-6
        or rim_max > flat_vertical[1] + 1e-6
    ):
        raise ValueError("No flat bottom/top land remains for camera front stop")
    rim_tangent_min = -CAMERA_FRONT_STOP_RIM_WIDTH / 2.0
    rim_tangent_max = CAMERA_FRONT_STOP_RIM_WIDTH / 2.0
    if (
        rim_tangent_min < flat_tangent[0] - 1e-6
        or rim_tangent_max > flat_tangent[1] + 1e-6
    ):
        raise ValueError("Camera front stop exceeds the flat body face")

    side_tangent = (tangent_min + tangent_max) / 2.0
    rim_vertical = (rim_min + rim_max) / 2.0
    return (
        (
            "Side_Lower",
            side_tangent,
            side_centers[0],
            CAMERA_FRONT_STOP_SIDE_WIDTH,
            CAMERA_FRONT_STOP_SIDE_HEIGHT,
        ),
        (
            "Side_Upper",
            side_tangent,
            side_centers[1],
            CAMERA_FRONT_STOP_SIDE_WIDTH,
            CAMERA_FRONT_STOP_SIDE_HEIGHT,
        ),
        (
            "Rim",
            0.0,
            rim_vertical,
            CAMERA_FRONT_STOP_RIM_WIDTH,
            CAMERA_FRONT_STOP_RIM_HEIGHT,
        ),
    )


def camera_support_pad_tangent_centers():
    """Resolve two body-bottom pads while avoiding a downward-facing button."""
    body_radial, body_tangent, body_vertical = mission1.canonical_body_bounds(
        CAMERA_UPSIDE_DOWN
    )
    flat_min = body_tangent[0] + mission1.BODY_CORNER_RADIUS
    flat_max = body_tangent[1] - mission1.BODY_CORNER_RADIUS
    half_width = CAMERA_SUPPORT_PAD_TANGENTIAL_WIDTH / 2.0
    low = flat_min + half_width
    high = flat_max - half_width
    if low >= high:
        raise ValueError("Camera support pads do not fit the body-bottom width")
    body_center = sum(body_tangent) / 2.0
    nominal_half_spacing = CAMERA_SUPPORT_PAD_TANGENTIAL_SPACING / 2.0
    obstacles = []
    button_radial, button_tangent, button_vertical = (
        mission1.canonical_top_button_bounds(CAMERA_UPSIDE_DOWN)
    )
    pad_radial_center = sum(body_radial) / 2.0
    pad_radial = (
        pad_radial_center - CAMERA_SUPPORT_PAD_RADIAL_LENGTH / 2.0,
        pad_radial_center + CAMERA_SUPPORT_PAD_RADIAL_LENGTH / 2.0,
    )
    radial_overlap = (
        pad_radial[0] < button_radial[1]
        and button_radial[0] < pad_radial[1]
    )
    if button_vertical[0] < body_vertical[0] - 1e-6 and radial_overlap:
        obstacles.append(
            (
                button_tangent[0] - CAMERA_SUPPORT_FEATURE_CLEARANCE,
                button_tangent[1] + CAMERA_SUPPORT_FEATURE_CLEARANCE,
            )
        )

    def valid(center):
        interval = (center - half_width, center + half_width)
        return low - 1e-6 <= center <= high + 1e-6 and not any(
            interval[0] < obstacle[1] and obstacle[0] < interval[1]
            for obstacle in obstacles
        )

    nominal = (
        body_center - nominal_half_spacing,
        body_center + nominal_half_spacing,
    )
    if valid(nominal[0]) and valid(nominal[1]):
        return nominal

    step = 0.25
    count = int(math.ceil((high - low) / step))
    candidates = [low + index * (high - low) / count for index in range(count + 1)]
    candidates = [center for center in candidates if valid(center)]
    pairs = []
    minimum_separation = (
        CAMERA_SUPPORT_PAD_TANGENTIAL_WIDTH + CAMERA_SUPPORT_PAD_MIN_GAP
    )
    for first_index, first in enumerate(candidates):
        for second in candidates[first_index + 1 :]:
            separation = second - first
            if separation < minimum_separation:
                continue
            score = (
                abs(separation - CAMERA_SUPPORT_PAD_TANGENTIAL_SPACING),
                abs((first + second) / 2.0 - body_center),
                -separation,
            )
            pairs.append((score, (first, second)))
    if not pairs:
        raise ValueError("No two camera support pads avoid bottom-side features")
    pairs.sort(key=lambda item: item[0])
    return pairs[0][1]


def resolved_camera_cradle_side_guide_height() -> float:
    """Keep the snug lower guide below the lens housing's slide path."""
    if (
        not CAMERA_CRADLE_SIDE_GUIDE_AUTO_CLEAR_LENS_PATH
        or resolved_camera_cradle_side_guide_radial_placement() != "front"
    ):
        return CAMERA_CRADLE_SIDE_GUIDE_HEIGHT
    _, _, body_vertical = mission1.canonical_body_bounds(CAMERA_UPSIDE_DOWN)
    body_bottom = body_vertical[0]
    lens_bottom = -mission1.LENS_FACE_HEIGHT / 2.0
    maximum_height = (
        lens_bottom
        - body_bottom
        - CAMERA_CRADLE_SIDE_GUIDE_LENS_PATH_CLEARANCE
    )
    return min(CAMERA_CRADLE_SIDE_GUIDE_HEIGHT, maximum_height)


def resolved_camera_cradle_side_guide_radial_placement() -> str:
    """Move an upside-down guide behind the low lens shoulder."""
    if (
        CAMERA_UPSIDE_DOWN
        and CAMERA_CRADLE_SIDE_GUIDE_RADIAL_PLACEMENT == "front"
    ):
        return "center"
    return CAMERA_CRADLE_SIDE_GUIDE_RADIAL_PLACEMENT


def eye_top_loading_slot_bottom_z() -> float:
    return camera_eye_center_z() + EYE_TOP_LOADING_SLOT_BOTTOM_OFFSET_Z


def camera_cradle_rear_guides_enabled() -> bool:
    """Rear stops are permanent only when the camera installs from above."""
    return CAMERA_CRADLE_REAR_GUIDE_ENABLED and EYE_TOP_LOADING_ENABLED


def resolved_visor_vertical_shift() -> float:
    if not VISOR_AUTO_CLEAR_CAMERA:
        return 0.0
    lens_top = camera_eye_center_z() + mission1.LENS_FACE_HEIGHT / 2.0
    required_bottom = lens_top + VISOR_CAMERA_VERTICAL_CLEARANCE
    return max(
        0.0,
        required_bottom - min(VISOR_BACK_BOTTOM_Z, VISOR_FRONT_BOTTOM_Z),
    )


def resolved_visor_back_inset() -> float:
    if not VISOR_AUTO_CLEAR_CAMERA:
        return VISOR_BACK_INSET
    body_radial = mission1.canonical_body_bounds(CAMERA_UPSIDE_DOWN)[0]
    body_front_from_surface = camera_lens_face_outset() + body_radial[1]
    maximum_safe_inset = max(
        -body_front_from_surface - VISOR_CAMERA_BODY_RADIAL_CLEARANCE,
        0.0,
    )
    maximum_safe_inset = min(
        maximum_safe_inset,
        VISOR_LID_SAFE_MAX_BACK_INSET,
    )
    return min(VISOR_BACK_INSET, maximum_safe_inset)


def resolved_visor_z(value: float) -> float:
    resolved = value + resolved_visor_vertical_shift()
    # The base owns the two fixed visor wings and the lid owns only the center
    # that passes through the U-slot.  Keeping the common visor profile at or
    # below the joint plane prevents either wing from entering the lid plate.
    if VISOR_AUTO_CLEAR_CAMERA:
        resolved = min(resolved, BASE_HEIGHT)
    return resolved


def eye_mouth_cutter_radial_bounds(camera):
    surface = camera["surface"]
    return (
        surface
        - BODY_WALL_THICKNESS
        - EYE_MOUTH_RECESS_DEPTH
        - EYE_MOUTH_FACE_INSET
        - EYE_MOUTH_CUTTER_INWARD_EXTRA,
        surface + EYE_MOUTH_CUTTER_OUTWARD_EXTENSION,
    )


def eye_lid_closure_radial_bounds(camera):
    """Return central tongue and inside backing-flange radial bounds."""
    # Key the removable upper eye closure directly behind the abstract front
    # datum plane, without adding annular material around the mouth.
    rim_backplane = eye_front_datum_plane(camera)
    backing_max = rim_backplane - EYE_LID_CLOSURE_RADIAL_CLEARANCE
    backing_min = backing_max - EYE_LID_CLOSURE_BACKING_THICKNESS
    main_min = backing_max - BOOLEAN_OVERLAP
    main_max = (
        camera["surface"]
        - EYE_MOUTH_FACE_INSET
        - EYE_LID_CLOSURE_RADIAL_CLEARANCE
    )
    if main_max <= main_min:
        raise ValueError("Eye-lid closure has no positive radial thickness")
    return (main_min, main_max), (backing_min, backing_max)


def camera_usb_side_name() -> str:
    if CAMERA_USB_SIDE == "auto":
        return "tangent_max" if CAMERA_UPSIDE_DOWN else "tangent_min"
    return CAMERA_USB_SIDE


def camera_usb_side_sign() -> float:
    return -1.0 if camera_usb_side_name() == "tangent_min" else 1.0


def camera_carrier_side_guide_specs(body_radial, body_tangent):
    """Return stout end-guide segments with an open cooling/USB middle."""
    side_specs = (
        (
            "tangent_min",
            body_tangent[0]
            - CAMERA_CARRIER_CAMERA_CLEARANCE
            - CAMERA_CARRIER_GUIDE_THICKNESS / 2.0,
        ),
        (
            "tangent_max",
            body_tangent[1]
            + CAMERA_CARRIER_CAMERA_CLEARANCE
            + CAMERA_CARRIER_GUIDE_THICKNESS / 2.0,
        ),
    )
    usb_side = camera_usb_side_name()
    radial_span = body_radial[1] - body_radial[0]
    end_length = min(
        CAMERA_CARRIER_SIDE_GUIDE_END_LENGTH,
        radial_span / 2.0,
    )
    usb_radial = camera_usb_local_access_bounds()[0]
    lens_half_width = mission1.LENS_FACE_WIDTH / 2.0
    lens_overhang_sides = set()
    if body_tangent[0] > -lens_half_width:
        lens_overhang_sides.add("tangent_min")
    if body_tangent[1] < lens_half_width:
        lens_overhang_sides.add("tangent_max")
    result = []
    for side_name, tangent in side_specs:
        enabled = (
            CAMERA_CARRIER_USB_SIDE_GUIDE_ENABLED
            if side_name == usb_side
            else CAMERA_CARRIER_NON_USB_SIDE_GUIDE_ENABLED
        )
        if not enabled:
            continue
        if side_name == usb_side:
            segments = (
                (
                    body_radial[0],
                    min(body_radial[1], usb_radial[0]),
                    "rear",
                ),
                (
                    max(body_radial[0], usb_radial[1]),
                    body_radial[1],
                    "front",
                ),
            )
            minimum_length = CAMERA_CARRIER_USB_GUIDE_MIN_SEGMENT_LENGTH
        else:
            segments = (
                (
                    body_radial[0],
                    body_radial[0] + end_length,
                    "rear",
                ),
                (
                    body_radial[1] - end_length,
                    body_radial[1],
                    "front",
                ),
            )
            minimum_length = 0.5
        for radial_min, radial_max, segment_name in segments:
            # The lens taper overhangs one asymmetric main-body side near the
            # front face.  A rectangular front guide there would collide with
            # the lens shoulder; the rear guide and opposite front datum still
            # locate the camera while leaving this area open to cooling air.
            if (
                segment_name == "front"
                and side_name in lens_overhang_sides
            ):
                continue
            if radial_max - radial_min < minimum_length:
                continue
            if segment_name == "rear":
                radial_min -= CAMERA_CARRIER_REAR_CORNER_OVERLAP
            result.append(
                (
                    side_name,
                    segment_name,
                    tangent,
                    radial_min,
                    radial_max,
                )
            )
    return tuple(result)


def camera_carrier_side_air_channel_widths(body_radial, body_tangent):
    """Return the largest unobstructed radial channel on each guided side."""
    widths = {}
    specs = camera_carrier_side_guide_specs(body_radial, body_tangent)
    for side_name in ("tangent_min", "tangent_max"):
        intervals = sorted(
            (
                max(body_radial[0], radial_min),
                min(body_radial[1], radial_max),
            )
            for side, _, _, radial_min, radial_max in specs
            if side == side_name
            and radial_max > body_radial[0]
            and radial_min < body_radial[1]
        )
        if not intervals:
            continue
        cursor = body_radial[0]
        largest_gap = 0.0
        for interval_min, interval_max in intervals:
            largest_gap = max(largest_gap, interval_min - cursor)
            cursor = max(cursor, interval_max)
        widths[side_name] = max(largest_gap, body_radial[1] - cursor)
    return widths


def camera_carrier_end_guide_specs(body_radial, body_tangent):
    """Return split rear stops and the compact front datum in local bounds."""
    body_tangent_center = sum(body_tangent) / 2.0
    rear_segment_width = (
        CAMERA_CARRIER_REAR_GUIDE_TOTAL_WIDTH
        - CAMERA_CARRIER_REAR_GUIDE_CENTER_AIR_GAP
    ) / 2.0
    rear_segment_offset = (
        CAMERA_CARRIER_REAR_GUIDE_CENTER_AIR_GAP + rear_segment_width
    ) / 2.0
    radial_rear_max = body_radial[0] - CAMERA_CARRIER_CAMERA_CLEARANCE
    radial_rear_min = radial_rear_max - CAMERA_CARRIER_GUIDE_THICKNESS
    result = []
    for rear_index, tangent_sign in enumerate((-1.0, 1.0), start=1):
        tangent_center = (
            body_tangent_center + tangent_sign * rear_segment_offset
        )
        tangent_min = tangent_center - rear_segment_width / 2.0
        tangent_max = tangent_center + rear_segment_width / 2.0
        if tangent_sign < 0.0:
            tangent_min -= CAMERA_CARRIER_REAR_CORNER_OVERLAP
        else:
            tangent_max += CAMERA_CARRIER_REAR_CORNER_OVERLAP
        result.append(
            (
                f"rear_{rear_index}",
                radial_rear_min,
                radial_rear_max,
                tangent_min,
                tangent_max,
            )
        )

    # Put the front datum on the broad flat body land beyond the lens/eye
    # housing, not at the battery-side corner where the protruding lens lives.
    lens_side_keepout = max(
        EYE_MOUTH_WIDTH / 2.0 + CAMERA_FRONT_STOP_WALL_LAND,
        mission1.LENS_SHOULDER_WIDTH / 2.0
        + CAMERA_LENS_OPENING_CLEARANCE,
    )
    # The front datum is stationary relative to the rotating carrier.  Resolve
    # its nominal inner tangential edge so every radial corner stays beyond the
    # assembled aperture guard throughout the configured yaw range, including
    # the clearance added by the final adaptive base-relief cutter.  Without
    # this transform-aware bound, a datum that clears at zero yaw can sweep
    # through the rounded lower eye corner by roughly 1--2 mm.
    if CAMERA_CARTRIDGE_WORM_ENABLED:
        pivot_tangents = (
            (
                -abs(ADJUSTABLE_CAMERA_PIVOT_TANGENTIAL),
                abs(ADJUSTABLE_CAMERA_PIVOT_TANGENTIAL),
            )
            if ADJUSTABLE_CAMERA_MIRROR_MECHANISM_BY_SIDE
            else (ADJUSTABLE_CAMERA_PIVOT_TANGENTIAL,)
        )
        pivot_radial = ADJUSTABLE_CAMERA_PIVOT_RADIAL
        front_radial_bounds = (
            body_radial[1] + CAMERA_CARRIER_CAMERA_CLEARANCE,
            body_radial[1]
            + CAMERA_CARRIER_CAMERA_CLEARANCE
            + CAMERA_CARRIER_GUIDE_THICKNESS
            - CAMERA_CARRIER_SWEEP_CUT_CLEARANCE,
        )
        guard_tangent = (
            EYE_MOUTH_WIDTH / 2.0
            + CAMERA_CARRIER_SWEEP_CUT_CLEARANCE
            + CAMERA_CARRIER_FRONT_STOP_EYE_MOUTH_MARGIN
        )
        negative_inner_limits = []
        positive_inner_limits = []
        for pivot_tangent in pivot_tangents:
            for yaw_delta in adjustable_yaw_samples(include_preview=True):
                yaw = math.radians(yaw_delta)
                sine = math.sin(yaw)
                cosine = math.cos(yaw)
                if cosine <= 0.0:
                    raise ValueError(
                        "Adjustable camera yaw must keep the carrier front "
                        "datum within +/-90 degrees of nominal"
                    )
                for radial in front_radial_bounds:
                    radial_term = sine * (radial - pivot_radial)
                    negative_inner_limits.append(
                        pivot_tangent
                        + (
                            -guard_tangent
                            - pivot_tangent
                            - radial_term
                        )
                        / cosine
                    )
                    positive_inner_limits.append(
                        pivot_tangent
                        + (
                            guard_tangent
                            - pivot_tangent
                            - radial_term
                        )
                        / cosine
                    )
        negative_guard_edge = min(negative_inner_limits)
        positive_guard_edge = max(positive_inner_limits)
    else:
        negative_guard_edge = -lens_side_keepout
        positive_guard_edge = lens_side_keepout
    negative_guard_edge = min(negative_guard_edge, -lens_side_keepout)
    positive_guard_edge = max(positive_guard_edge, lens_side_keepout)
    flat_tangent_min = body_tangent[0] + mission1.BODY_CORNER_RADIUS
    flat_tangent_max = body_tangent[1] - mission1.BODY_CORNER_RADIUS
    negative_room = negative_guard_edge - flat_tangent_min
    positive_room = flat_tangent_max - positive_guard_edge
    if negative_room >= positive_room:
        front_tangent_max = negative_guard_edge
        front_tangent_min = (
            front_tangent_max - CAMERA_CARRIER_FRONT_STOP_WIDTH
        )
    else:
        front_tangent_min = positive_guard_edge
        front_tangent_max = (
            front_tangent_min + CAMERA_CARRIER_FRONT_STOP_WIDTH
        )
    front_radial_min = body_radial[1] + CAMERA_CARRIER_CAMERA_CLEARANCE
    result.append(
        (
            "front_stop",
            front_radial_min,
            front_radial_min
            + CAMERA_CARRIER_GUIDE_THICKNESS
            - CAMERA_CARRIER_SWEEP_CUT_CLEARANCE,
            front_tangent_min,
            front_tangent_max,
        )
    )
    return tuple(result)


def camera_carrier_tray_airflow_metrics(body_radial, body_tangent):
    """Return vent intervals, open area, and camera-plan open-area ratio."""
    tray_radial_min = body_radial[0] - CAMERA_CARRIER_TRAY_RADIAL_MARGIN
    tray_radial_max = body_radial[1] + CAMERA_CARRIER_TRAY_RADIAL_MARGIN
    tray_tangent_min = (
        body_tangent[0] - CAMERA_CARRIER_TRAY_TANGENTIAL_MARGIN
    )
    tray_tangent_max = (
        body_tangent[1] + CAMERA_CARRIER_TRAY_TANGENTIAL_MARGIN
    )
    vent_radial_min = tray_radial_min + CAMERA_CARRIER_TRAY_FRAME_WIDTH
    vent_radial_max = tray_radial_max - CAMERA_CARRIER_TRAY_FRAME_WIDTH
    vent_tangent_min = tray_tangent_min + CAMERA_CARRIER_TRAY_FRAME_WIDTH
    vent_tangent_max = tray_tangent_max - CAMERA_CARRIER_TRAY_FRAME_WIDTH
    half_rail = CAMERA_CARRIER_SUPPORT_RAIL_WIDTH / 2.0
    front_stop_spec = camera_carrier_end_guide_specs(
        body_radial,
        body_tangent,
    )[-1]
    front_stop_tangent_center = (
        front_stop_spec[3] + front_stop_spec[4]
    ) / 2.0
    retained_specs = [
        (tangent, half_rail)
        for tangent in camera_support_pad_tangent_centers()
    ]
    retained_specs.append(
        (
            front_stop_tangent_center,
            CAMERA_CARRIER_FRONT_STOP_ROOT_RAIL_WIDTH / 2.0,
        )
    )
    retained_intervals = sorted(
        (
            max(vent_tangent_min, tangent - retained_half_width),
            min(vent_tangent_max, tangent + retained_half_width),
        )
        for tangent, retained_half_width in retained_specs
        if tangent + retained_half_width > vent_tangent_min
        and tangent - retained_half_width < vent_tangent_max
    )
    cursor = vent_tangent_min
    vent_intervals = []
    for interval_min, interval_max in retained_intervals:
        if interval_min > cursor + 0.5:
            vent_intervals.append((cursor, interval_min))
        cursor = max(cursor, interval_max)
    if cursor < vent_tangent_max - 0.5:
        vent_intervals.append((cursor, vent_tangent_max))
    vent_open_area = (
        max(vent_radial_max - vent_radial_min, 0.0)
        * sum(
            tangent_max - tangent_min
            for tangent_min, tangent_max in vent_intervals
        )
    )
    camera_plan_area = (
        (body_radial[1] - body_radial[0])
        * (body_tangent[1] - body_tangent[0])
    )
    return (
        vent_radial_min,
        vent_radial_max,
        tuple(vent_intervals),
        vent_open_area,
        vent_open_area / max(camera_plan_area, 1e-6),
    )


def rounded_rectangle_area(width, height, radius):
    radius = min(max(radius, 0.0), width / 2.0, height / 2.0)
    return width * height - (4.0 - math.pi) * radius * radius


def forced_airflow_path_metrics():
    """Return gross/effective fan and lens-annulus exhaust areas."""
    if lid_fan_enabled():
        dimensions = lid_fan_reference_dimensions()
        opening_radius = dimensions["opening"] / 2.0
        hub_radius = dimensions["hub"] / 2.0
        fan_open_area = lid_fan_count() * math.pi * opening_radius**2
        fan_effective_open_area = lid_fan_count() * math.pi * (
            opening_radius**2 - hub_radius**2
        )
    else:
        fan_open_area = (
            2.0 * math.pi * (REAR_FAN_AIR_OPENING_DIAMETER / 2.0) ** 2
        )
        fan_effective_open_area = 2.0 * math.pi * (
            (REAR_FAN_AIR_OPENING_DIAMETER / 2.0) ** 2
            - (REAR_FAN_HUB_DIAMETER / 2.0) ** 2
        )
    eye_area = rounded_rectangle_area(
        EYE_MOUTH_WIDTH,
        EYE_MOUTH_HEIGHT,
        EYE_MOUTH_CORNER_RADIUS,
    )
    lens_area = rounded_rectangle_area(
        mission1.LENS_FACE_WIDTH,
        mission1.LENS_FACE_HEIGHT,
        mission1.LENS_FACE_CORNER_RADIUS,
    )
    exhaust_area = 2.0 * max(eye_area - lens_area, 0.0)
    minimum_edge_gap = min(
        (EYE_MOUTH_WIDTH - mission1.LENS_FACE_WIDTH) / 2.0,
        (EYE_MOUTH_HEIGHT - mission1.LENS_FACE_HEIGHT) / 2.0,
    )
    return (
        fan_open_area,
        fan_effective_open_area,
        exhaust_area,
        exhaust_area / max(fan_open_area, 1e-6),
        exhaust_area / max(fan_effective_open_area, 1e-6),
        minimum_edge_gap,
    )


def installed_fan_gasket_thickness() -> float:
    """Return the axial fan offset created by the installed soft gasket."""
    return (
        FAN_GASKET_THICKNESS
        if rear_wall_fans_enabled() and FAN_VIBRATION_ISOLATION_ENABLED
        else 0.0
    )


def camera_rear_face_pose(camera, yaw_delta=0.0):
    """Return the posed rear-body face center and its in-plane basis."""
    body_radial, body_tangent, body_vertical = (
        mission1.canonical_body_bounds(CAMERA_UPSIDE_DOWN)
    )
    tangent_center = sum(body_tangent) / 2.0
    vertical_center = sum(body_vertical) / 2.0
    if camera_is_adjustable(camera):
        center = adjustable_camera_local_point(
            camera,
            body_radial[0],
            tangent_center,
            camera_eye_center_z() + vertical_center,
            yaw_delta,
        )
        angle_deg = camera["angle"] + yaw_delta
    else:
        lens_face_radius = camera["radial"] + CAMERA_BODY_DEPTH / 2.0
        center = axis_point(
            camera["angle"],
            lens_face_radius + body_radial[0],
            camera["eye_tangent"] + tangent_center,
            camera_eye_center_z() + vertical_center,
        )
        angle_deg = camera["angle"]
    angle = math.radians(angle_deg)
    normal = Vector((math.cos(angle), math.sin(angle), 0.0))
    tangent_axis = Vector((-math.sin(angle), math.cos(angle), 0.0))
    return {
        "center": center,
        "normal": normal,
        "tangent_axis": tangent_axis,
        "tangent_span": body_tangent[1] - body_tangent[0],
        "vertical_span": body_vertical[1] - body_vertical[0],
    }


def fan_discharge_geometry(station):
    """Return the installed fan's inward discharge origin and direction."""
    angle = math.radians(station["wall_angle_deg"])
    outward_normal = Vector((math.cos(angle), math.sin(angle), 0.0))
    inward_direction = -outward_normal
    face_center = Vector(station["face_center"])
    # An internal fan discharges from its inward face.  An external intake
    # discharges into the wall opening, so the useful internal plume begins at
    # the seating plane rather than behind the exterior fan body.
    internal_discharge_offset = (
        installed_fan_gasket_thickness() + REAR_FAN_DEPTH
        if REAR_FAN_PAD_INSIDE
        else 0.0
    )
    return (
        face_center + inward_direction * internal_discharge_offset,
        inward_direction,
    )


def fan_camera_rear_wash_metrics(station, camera, yaw_delta=0.0):
    """Sample the camera rear face inside one mildly divergent fan plume."""
    origin, direction = fan_discharge_geometry(station)
    face = camera_rear_face_pose(camera, yaw_delta)
    denominator = direction.dot(face["normal"])
    incidence_cosine = abs(denominator)
    if abs(denominator) <= 1e-9:
        return 0.0, incidence_cosine, float("inf")
    centerline_distance = (
        (face["center"] - origin).dot(face["normal"]) / denominator
    )
    if centerline_distance <= 0.0:
        return 0.0, incidence_cosine, centerline_distance

    grid = CAMERA_COOLING_WASH_SAMPLE_GRID
    tangent_span = face["tangent_span"]
    vertical_span = face["vertical_span"]
    plume_slope = math.tan(
        math.radians(CAMERA_COOLING_FAN_PLUME_HALF_ANGLE_DEG)
    )
    initial_radius = REAR_FAN_AIR_OPENING_DIAMETER / 2.0
    washed = 0
    for tangent_index in range(grid):
        tangent_offset = tangent_span * (
            (tangent_index + 0.5) / grid - 0.5
        )
        for vertical_index in range(grid):
            vertical_offset = vertical_span * (
                (vertical_index + 0.5) / grid - 0.5
            )
            point = (
                face["center"]
                + face["tangent_axis"] * tangent_offset
                + Vector((0.0, 0.0, vertical_offset))
            )
            delta = point - origin
            axial_distance = delta.dot(direction)
            if axial_distance <= 0.0:
                continue
            transverse_squared = max(
                delta.length_squared - axial_distance * axial_distance,
                0.0,
            )
            plume_radius = initial_radius + axial_distance * plume_slope
            if transverse_squared <= plume_radius * plume_radius:
                washed += 1
    return (
        washed / float(grid * grid),
        incidence_cosine,
        centerline_distance,
    )


def resolved_rear_fan_camera_pairing(footprint, cameras):
    """Pair each rear fan with the camera on the same side of the case.

    Both possible pairings meet the configured rear-face wash threshold, but
    the opposite-side pairing makes the two planar guide ducts cross.  A
    printable pair of full-height ducts cannot pass through itself, so retain
    the non-crossing side order and let the wash validators enforce cooling.
    """
    stations = sorted(
        (
            rear_fan_station_geometry(footprint, tangent)
            for tangent in rear_fan_center_tangents()
        ),
        key=lambda station: station["face_center"].y,
    )
    cameras_by_side = sorted(
        cameras,
        key=lambda camera: camera_rear_face_pose(camera, 0.0)["center"].y,
    )
    return tuple(zip(stations, cameras_by_side))


def validate_forced_air_camera_wash(footprint, cameras):
    """Require one rear fan to wash each camera throughout its yaw sweep."""
    if not rear_wall_fans_enabled():
        return
    pairing = resolved_rear_fan_camera_pairing(footprint, cameras)
    for fan_index, (station, camera) in enumerate(pairing, start=1):
        yaw_samples = (
            adjustable_yaw_samples(include_preview=True)
            if camera_is_adjustable(camera)
            else (0.0,)
        )
        records = [
            (
                yaw_delta,
                *fan_camera_rear_wash_metrics(
                    station,
                    camera,
                    yaw_delta,
                ),
            )
            for yaw_delta in yaw_samples
        ]
        worst = min(records, key=lambda record: record[1])
        minimum_incidence = min(record[2] for record in records)
        if worst[3] <= 0.0:
            raise ValueError(
                f"Rear fan {fan_index} points away from camera "
                f"{camera['index']} at yaw {worst[0]:+.2f}"
            )
        if minimum_incidence < CAMERA_COOLING_MIN_FAN_TO_REAR_FACE_COSINE:
            raise ValueError(
                f"Rear fan {fan_index} grazes camera {camera['index']} too "
                f"obliquely: {minimum_incidence:.3f} < "
                f"{CAMERA_COOLING_MIN_FAN_TO_REAR_FACE_COSINE:.3f}"
            )
        if worst[1] < CAMERA_COOLING_MIN_REAR_FACE_WASH_RATIO:
            raise ValueError(
                f"Rear fan {fan_index} washes too little of camera "
                f"{camera['index']} at yaw {worst[0]:+.2f}: "
                f"{worst[1]:.3f} < "
                f"{CAMERA_COOLING_MIN_REAR_FACE_WASH_RATIO:.3f}. Adjust "
                "REAR_FAN_CENTER_TANGENTS or the plume/coverage settings."
            )
        print(
            "FORCED_AIR_CAMERA_WASH "
            f"fan={fan_index} camera={camera['index']} "
            f"minimum_ratio={worst[1]:.3f} "
            f"worst_yaw={worst[0]:+.2f}deg "
            f"minimum_incidence_cosine={minimum_incidence:.3f} "
            f"rear_face_distance={worst[3]:.1f}mm "
            f"under_camera_gap={CAMERA_FLOOR_CLEARANCE:.1f}mm"
        )
    print(
        "FORCED_AIR_CAMERA_WASH PASS "
        f"plume_half_angle={CAMERA_COOLING_FAN_PLUME_HALF_ANGLE_DEG:.1f}deg "
        f"minimum_rear_face_ratio="
        f"{CAMERA_COOLING_MIN_REAR_FACE_WASH_RATIO:.3f} "
        f"yaw_step={ADJUSTABLE_CAMERA_SWEEP_STEP_DEG:.1f}deg"
    )


def validate_final_forced_air_camera_wash(
    footprint,
    cameras,
    camera_mockups,
    base,
    lid,
    camera_brackets,
    camera_carrier=None,
    camera_worm=None,
    worm_bearing_caps=(),
    stationary_hardware=(),
    airflow_guide_layout=None,
):
    """Ray-test useful fan wash through the completed installed geometry."""
    if (
        not rear_wall_fans_enabled()
        or fan_acoustic_attenuator_enabled()
        or not VALIDATE_REAR_FAN_BODY_CLEARANCE
    ):
        return
    pairing = resolved_rear_fan_camera_pairing(footprint, cameras)
    guided_direct_flow = (
        airflow_guide_layout is not None
        and airflow_guide_layout.get("source") == "rear_camera_funnels"
    )
    if guided_direct_flow and not base.get(
        "air_guide_final_open_channels_validated",
        False,
    ):
        raise RuntimeError(
            "Guided rear-fan wash requires final-base open-channel "
            "validation"
        )
    fixed_obstacles = [
        lid,
        *camera_brackets,
        *worm_bearing_caps,
        *(part for part in stationary_hardware if part is not None),
    ]
    if not guided_direct_flow:
        fixed_obstacles.insert(0, base)
    if camera_worm is not None:
        fixed_obstacles.append(camera_worm)
    fixed_records = [object_bvh_record(obj) for obj in fixed_obstacles]
    fixed_record_names = [obj.name for obj in fixed_obstacles]
    grid = CAMERA_COOLING_WASH_SAMPLE_GRID
    plume_slope = math.tan(
        math.radians(CAMERA_COOLING_FAN_PLUME_HALF_ANGLE_DEG)
    )
    initial_radius = REAR_FAN_AIR_OPENING_DIAMETER / 2.0
    moving_camera = adjustable_camera(cameras)
    mockups_by_index = {
        camera["index"]: mockup
        for camera, mockup in zip(cameras, camera_mockups)
    }
    try:
        for fan_index, (station, camera) in enumerate(pairing, start=1):
            assembly_yaws = (
                adjustable_yaw_samples(include_preview=True)
                if moving_camera is not None
                else (0.0,)
            )
            pose_records = []
            for assembly_yaw in assembly_yaws:
                camera_yaw = assembly_yaw if camera_is_adjustable(camera) else 0.0
                origin, direction = fan_discharge_geometry(station)
                origin = origin + direction * max(
                    BOOLEAN_CLEANUP_DISTANCE * 2.0,
                    0.10,
                )
                face = camera_rear_face_pose(camera, camera_yaw)
                incidence = abs(direction.dot(face["normal"]))
                posed_carrier = None
                pose_bvh = []
                pose_record_names = []
                pose_owned_objects = []
                if camera_carrier is not None and moving_camera is not None:
                    posed_carrier = posed_carrier_copy(
                        camera_carrier,
                        moving_camera,
                        assembly_yaw,
                        f"Final_Fan_Wash_Carrier_{fan_index}_"
                        f"{assembly_yaw:+.1f}",
                    )
                    pose_bvh.append(object_bvh_record(posed_carrier))
                    pose_record_names.append(posed_carrier.name)
                    pose_owned_objects.append(posed_carrier)
                for other_camera in cameras:
                    if other_camera["index"] == camera["index"]:
                        continue
                    other_mockup = mockups_by_index.get(other_camera["index"])
                    if other_mockup is None:
                        continue
                    if camera_is_adjustable(other_camera):
                        sibling = posed_camera_copy(
                            other_mockup,
                            other_camera,
                            assembly_yaw,
                            f"Final_Fan_Wash_Sibling_Camera_"
                            f"{other_camera['index']}_{assembly_yaw:+.1f}",
                        )
                        pose_owned_objects.append(sibling)
                    else:
                        sibling = other_mockup
                    pose_bvh.append(object_bvh_record(sibling))
                    pose_record_names.append(
                        f"sibling_camera_{other_camera['index']}"
                    )
                records = (*fixed_records, *pose_bvh)
                record_names = (
                    *fixed_record_names,
                    *pose_record_names,
                )
                occlusion_counts = [0] * len(records)
                washed = 0
                geometrically_washed = 0
                try:
                    for tangent_index in range(grid):
                        tangent_offset = face["tangent_span"] * (
                            (tangent_index + 0.5) / grid - 0.5
                        )
                        for vertical_index in range(grid):
                            vertical_offset = face["vertical_span"] * (
                                (vertical_index + 0.5) / grid - 0.5
                            )
                            point = (
                                face["center"]
                                + face["tangent_axis"] * tangent_offset
                                + Vector((0.0, 0.0, vertical_offset))
                            )
                            delta = point - origin
                            axial = delta.dot(direction)
                            if axial <= 0.0:
                                continue
                            transverse_squared = max(
                                delta.length_squared - axial * axial,
                                0.0,
                            )
                            plume_radius = initial_radius + axial * plume_slope
                            if transverse_squared > plume_radius * plume_radius:
                                continue
                            geometrically_washed += 1
                            blocked = False
                            for obstacle_index, (tree, inverse, bm) in enumerate(
                                records
                            ):
                                if point_inside_closed_bvh(
                                    tree,
                                    inverse @ origin,
                                ) or segment_intersects_bvh_record(
                                    origin,
                                    point,
                                    (tree, inverse, bm),
                                    endpoint_margin=0.50,
                                ):
                                    occlusion_counts[obstacle_index] += 1
                                    blocked = True
                            if not blocked:
                                washed += 1
                finally:
                    for _tree, _inverse, bm in pose_bvh:
                        bm.free()
                    for owned in pose_owned_objects:
                        bpy.data.objects.remove(owned, do_unlink=True)
                ratio = washed / float(grid * grid)
                pose_records.append(
                    (
                        assembly_yaw,
                        ratio,
                        incidence,
                        geometrically_washed,
                        tuple(zip(record_names, occlusion_counts)),
                    )
                )
            worst = min(pose_records, key=lambda record: record[1])
            minimum_incidence = min(record[2] for record in pose_records)
            if minimum_incidence < CAMERA_COOLING_MIN_FAN_TO_REAR_FACE_COSINE:
                raise RuntimeError(
                    f"Final rear fan {fan_index} reaches camera "
                    f"{camera['index']} too obliquely: {minimum_incidence:.3f}"
                )
            if worst[1] < CAMERA_COOLING_MIN_REAR_FACE_WASH_RATIO:
                raise RuntimeError(
                    f"Final installed hardware blocks rear fan {fan_index} "
                    f"wash of camera {camera['index']} at assembly yaw "
                    f"{worst[0]:+.2f}: {worst[1]:.3f} < "
                    f"{CAMERA_COOLING_MIN_REAR_FACE_WASH_RATIO:.3f}; "
                    f"geometric_candidate_cells={worst[3]} "
                    f"occlusions={worst[4]}"
                )
            print(
                "FINAL_FORCED_AIR_CAMERA_WASH "
                f"fan={fan_index} camera={camera['index']} "
                f"minimum_unoccluded_ratio={worst[1]:.3f} "
                f"worst_assembly_yaw={worst[0]:+.2f}deg "
                f"candidate_cells={worst[3]} "
                f"minimum_incidence_cosine={minimum_incidence:.3f} "
                f"occlusions={worst[4]}"
            )
    finally:
        for _tree, _inverse, bm in fixed_records:
            bm.free()
    print(
        "FINAL_FORCED_AIR_CAMERA_WASH PASS "
        f"flow_model={'guided_route' if guided_direct_flow else 'direct_ray'} "
        f"final_base_open_channels_validated={guided_direct_flow} "
        "occluders=lid,brackets,carrier,worm,caps,sibling_camera "
        f"yaw_step={ADJUSTABLE_CAMERA_SWEEP_STEP_DEG:.2f}deg"
    )


def camera_usb_local_access_bounds():
    body_radial, body_tangent, body_vertical = mission1.canonical_body_bounds(
        CAMERA_UPSIDE_DOWN
    )
    radial_center = (
        sum(body_radial) / 2.0
        + CAMERA_USB_PORT_RADIAL_OFFSET_FROM_BODY_CENTER
    )
    radial_half = (
        CAMERA_USB_PORT_RADIAL_WIDTH / 2.0
        + CAMERA_USB_ACCESS_RADIAL_CLEARANCE
    )
    vertical_center = (
        body_vertical[0] + CAMERA_USB_PORT_CENTER_ABOVE_BODY_BOTTOM
    )
    vertical_half = (
        CAMERA_USB_PORT_HEIGHT / 2.0
        + CAMERA_USB_ACCESS_VERTICAL_CLEARANCE
    )
    side_sign = camera_usb_side_sign()
    body_side = body_tangent[0] if side_sign < 0.0 else body_tangent[1]
    if side_sign < 0.0:
        tangent = (
            body_side - CAMERA_USB_PLUG_OUTWARD_DEPTH,
            body_side + CAMERA_USB_PLUG_BODY_OVERLAP,
        )
    else:
        tangent = (
            body_side - CAMERA_USB_PLUG_BODY_OVERLAP,
            body_side + CAMERA_USB_PLUG_OUTWARD_DEPTH,
        )
    return (
        (radial_center - radial_half, radial_center + radial_half),
        tangent,
        (vertical_center - vertical_half, vertical_center + vertical_half),
    )


def bottom_mount_nut_pocket_across_flats() -> float:
    return BOTTOM_MOUNT_NUT_ACROSS_FLATS - BOTTOM_MOUNT_NUT_PRESS_INTERFERENCE


def bottom_mount_nut_seat_z() -> float:
    return BOTTOM_THICKNESS


def bottom_mount_nut_snap_shoulder_z() -> float:
    return (
        bottom_mount_nut_seat_z()
        + BOTTOM_MOUNT_NUT_THICKNESS
        + BOTTOM_MOUNT_NUT_THICKNESS_TOLERANCE
        + BOTTOM_MOUNT_NUT_SNAP_LIP_RETENTION_CLEARANCE
    )


def bottom_mount_nut_snap_relief_base_z() -> float:
    return (
        bottom_mount_nut_snap_shoulder_z()
        - BOTTOM_MOUNT_NUT_SNAP_FLEX_HEIGHT
    )


def bottom_mount_nut_holder_top_z() -> float:
    return (
        bottom_mount_nut_snap_shoulder_z()
        + BOTTOM_MOUNT_NUT_SNAP_LIP_HEIGHT
    )


def bottom_mount_feature_radius() -> float:
    if BOTTOM_MOUNT_NUT_HOLDER_ENABLED:
        return BOTTOM_MOUNT_NUT_HOLDER_OUTER_DIAMETER / 2.0
    return BOTTOM_MOUNT_HOLE_DIAMETER / 2.0


def bottom_keystone_mount_plan_dimensions():
    """Return the full Python-generated socket-housing footprint."""
    return (
        BOTTOM_KEYSTONE_SOCKET_OUTER_X,
        BOTTOM_KEYSTONE_SOCKET_OUTER_Y,
    )


def bottom_keystone_socket_inner_clear_x() -> float:
    return (
        BOTTOM_KEYSTONE_SOCKET_OUTER_X
        - 2.0 * BOTTOM_KEYSTONE_SOCKET_WALL_THICKNESS
    )


def bottom_keystone_socket_profile_yz():
    """Return the clockwise Y/Z outline of the socket's open cavity.

    Extruding this profile across the clear X span describes the void inside
    the housing.  Keeping the asymmetric rail and lip stations explicit makes
    the snap behavior configurable without embedding an STL vertex table.
    """
    outside_y0 = -BOTTOM_KEYSTONE_SOCKET_OUTER_Y / 2.0
    front_inner_y = outside_y0 + BOTTOM_KEYSTONE_SOCKET_WALL_THICKNESS
    rear_inner_y = -front_inner_y
    front_lower_tip_y = (
        front_inner_y
        + BOTTOM_KEYSTONE_SOCKET_FRONT_LOWER_RAIL_PROJECTION
    )
    rear_lower_platform_y = (
        rear_inner_y
        - BOTTOM_KEYSTONE_SOCKET_REAR_LOWER_RAIL_PROJECTION
    )
    rear_lower_ramp_tip_y = (
        rear_lower_platform_y
        - BOTTOM_KEYSTONE_SOCKET_REAR_LOWER_RAMP_RUN
    )
    front_upper_tip_y = (
        front_inner_y + BOTTOM_KEYSTONE_SOCKET_UPPER_LIP_PROJECTION
    )
    rear_upper_tip_y = (
        rear_inner_y - BOTTOM_KEYSTONE_SOCKET_UPPER_LIP_PROJECTION
    )
    front_upper_ramp_top_y = (
        front_upper_tip_y - BOTTOM_KEYSTONE_SOCKET_UPPER_RAMP_RUN
    )
    rear_upper_ramp_top_y = (
        rear_upper_tip_y + BOTTOM_KEYSTONE_SOCKET_UPPER_RAMP_RUN
    )
    upper_underside_z = (
        BOTTOM_KEYSTONE_SOCKET_HEIGHT
        - BOTTOM_KEYSTONE_SOCKET_UPPER_LIP_DEPTH
    )
    upper_nose_top_z = (
        upper_underside_z
        + BOTTOM_KEYSTONE_SOCKET_UPPER_LIP_NOSE_HEIGHT
    )
    lower_rail_z = BOTTOM_KEYSTONE_SOCKET_LOWER_RAIL_HEIGHT
    return (
        (front_inner_y, upper_underside_z),
        (front_upper_tip_y, upper_underside_z),
        (front_upper_tip_y, upper_nose_top_z),
        (front_upper_ramp_top_y, BOTTOM_KEYSTONE_SOCKET_HEIGHT),
        (front_upper_tip_y, BOTTOM_KEYSTONE_SOCKET_HEIGHT),
        (rear_upper_tip_y, BOTTOM_KEYSTONE_SOCKET_HEIGHT),
        (rear_upper_ramp_top_y, BOTTOM_KEYSTONE_SOCKET_HEIGHT),
        (rear_upper_tip_y, upper_nose_top_z),
        (rear_upper_tip_y, upper_underside_z),
        (rear_inner_y, upper_underside_z),
        (rear_inner_y, lower_rail_z),
        (rear_lower_platform_y, lower_rail_z),
        (
            rear_lower_ramp_tip_y,
            BOTTOM_KEYSTONE_SOCKET_REAR_LOWER_RAMP_TIP_HEIGHT,
        ),
        (rear_lower_ramp_tip_y, 0.0),
        (front_lower_tip_y, 0.0),
        (front_lower_tip_y, lower_rail_z),
        (front_inner_y, lower_rail_z),
    )


def bottom_keystone_socket_profile_area() -> float:
    profile = bottom_keystone_socket_profile_yz()
    return abs(
        sum(
            y0 * z1 - z0 * y1
            for (y0, z0), (y1, z1) in zip(
                profile,
                (*profile[1:], profile[0]),
            )
        )
    ) / 2.0


def bottom_keystone_socket_expected_volume() -> float:
    return (
        BOTTOM_KEYSTONE_SOCKET_OUTER_X
        * BOTTOM_KEYSTONE_SOCKET_OUTER_Y
        * BOTTOM_KEYSTONE_SOCKET_HEIGHT
        - bottom_keystone_socket_inner_clear_x()
        * bottom_keystone_socket_profile_area()
    )


def bottom_keystone_socket_module_bottom_z() -> float:
    """The installed cartridge begins above the native snap housing."""
    return BOTTOM_KEYSTONE_SOCKET_HEIGHT


